                           (*key, int(row["revision"]), row["body"], int(bool(row["deleted"]))))
                changed += 1
            db.execute("COMMIT")
            return {"repaired": changed}
        except BaseException:
            self._rollback(db)
            raise
        finally:
            db.close()
