  assert.equal(state.base.pump.revision, '5');
  assert.deepEqual(state.pending.map(p => p.mutation), ['w', 'later', 'q']);
  assert.deepEqual(reduce(state, {type: 'SEND_BATCH', batch: 'b', count: 1}).batch.wire, wire);
