     def __init__(self, path, fault=None):
         self.path = str(path)
         self.fault = fault
         db = self.connect()
         try:
             if self._initialized(db):
                 return
             db.execute("BEGIN IMMEDIATE")
             for statement in SCHEMA.split(";"):
                 if statement.strip():
                     db.execute(statement)
